}

contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint depositAmount, uint unlockTime, uint collectAmount) public payable {
        require(address(this).balance >= depositAmount + collectAmount);
        require(collectAmount > 0);

        // Make the contract eligible for Collect: enough balance and unlock time <= now.
        c.Put{value: depositAmount + 1 ether}(0);

        (uint unlockBefore, uint balanceBefore) = c.Acc(address(this));

        // Ensure the collect amount is at least the minimum sum and does not exceed the balance.
        uint effectiveCollect = collectAmount;
        if (effectiveCollect < 1 ether) {
            effectiveCollect = 1 ether;
        }
        if (effectiveCollect > balanceBefore) {
            effectiveCollect = balanceBefore;
        }

        // Use a low-level call to Collect so we can handle a potential revert.
        (bool sent, ) = address(c).call(
            abi.encodeWithSignature("Collect(uint256)", effectiveCollect)
        );

        (uint unlockAfter, uint balanceAfter) = c.Acc(address(this));

        // General rule: a successful Collect reduces the caller's recorded balance by exactly
        // the collected amount and leaves the unlock time unchanged; otherwise neither balance
        // nor unlock time changes.
        if (sent) {
            assert(balanceAfter == balanceBefore - effectiveCollect && unlockAfter == unlockBefore);
        } else {
            assert(balanceAfter == balanceBefore && unlockAfter == unlockBefore);
        }
    }

    receive() external payable {}
}

